import{_ as r}from"./chunks/one-entry-per-language.B5385FGC.js";import{_ as o,o as i,c as a,a0 as n}from"./chunks/framework.BL79I5mR.js";const s="/docs/assets/competency-configuration.DdamzEu8.png",l="/docs/assets/add-custom-property.CP0vDsds.png",p="/docs/assets/new-competency-property.3aWqupYq.png",c="/docs/assets/limit-values-competency.CcxVZcEH.png",m="/docs/assets/limit-values-enabled-competency.Cwr0My3b.png",d="/docs/assets/limit-concepts.CXOYPYEo.png",h="/docs/assets/limit-by-type.DLLUbENS.png",g="/docs/assets/competency-limited-by-type.DMPEu4uz.png",y="/docs/assets/competency-properties.B11nSu2-.png",u="/docs/assets/restrict-competency-types.BFWcr46D.png",f="/docs/assets/permitted-values.DgSjeClI.png",b="/docs/assets/allow-levels.BVi0tkOr.png",v="/docs/assets/restrict-levels.DgVAypmm.png",w="/docs/assets/enforced-levels.DBkGYQnm.png",C="/docs/assets/add-level.Bf9Yk7zv.png",k="/docs/assets/add-new-level.Bf4UoK_f.png",q="/docs/assets/apply-selected.CQ0AFrHL.png",T="/docs/assets/competency-relationships-configuration.C6HSl19j.png",_="/docs/assets/display-options.Py5jHRe0.png",t="/docs/assets/relationship-types.BSra4tdN.png",S="/docs/assets/relationship-types-enabled.DQXO5aks.png",P="/docs/assets/manage-relationships.AyDcXAqg.png",x="/docs/assets/resource-alignment-configuration.qfuuqDx5.png",M=JSON.parse('{"title":"Competency Property Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/competency-properties/index.md","filePath":"authoring/competency-properties/README.md"}'),L={name:"authoring/competency-properties/index.md"};function R(A,e,D,E,N,O){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="competency-property-configuration" tabindex="-1">Competency Property Configuration <a class="header-anchor" href="#competency-property-configuration" aria-label="Permalink to &quot;Competency Property Configuration&quot;">​</a></h1><p>Competency properties are the values that can be added, edited, and deleted for competency objects. Default competency properties are <em><strong>id, name, description,</strong></em> and <em><strong>type</strong></em>. Properties added here will be displayed when editing competency level objects in the framework editor.</p><p><img src="'+s+'" alt="Competency Configuration"></p><h2 id="property-fields" tabindex="-1">Property Fields <a class="header-anchor" href="#property-fields" aria-label="Permalink to &quot;Property Fields&quot;">​</a></h2><p>Certain property fields can be modified directly from the property list:</p><ul><li><em><strong>display label</strong></em> - label to be displayed in form inputs for that property</li><li><em><strong>description</strong></em> - description of this property</li><li><em><strong>display category</strong></em> - category (if any) under which the property is displayed in form inputs</li><li><em><strong>required</strong></em> - property required toggle</li><li><em><strong>display priority</strong></em> - priority in which the property is displayed in form inputs <ul><li><em>primary, secondary, or tertiary</em></li></ul></li></ul><p>At the competency level the following static rules apply:</p><ul><li>The <em><strong>id</strong></em> property is <em>required</em></li><li>The <em><strong>name</strong></em> property is <em>required</em> and has a display priority of <em>primary</em></li></ul><h2 id="custom-competency-properties" tabindex="-1">Custom Competency Properties <a class="header-anchor" href="#custom-competency-properties" aria-label="Permalink to &quot;Custom Competency Properties&quot;">​</a></h2><p>Custom properties can be added to a competency by clicking the <em><strong>add custom competency property</strong></em> button.</p><p><img src="'+l+'" alt="Add Custom Competency Property"></p><p>Once clicked, the <em><strong>New Competency Property</strong></em> dialogue window is displayed.</p><p><img src="'+p+'" alt="New Competency Property"></p><h3 id="custom-competency-property-fields" tabindex="-1">Custom Competency Property Fields <a class="header-anchor" href="#custom-competency-property-fields" aria-label="Permalink to &quot;Custom Competency Property Fields&quot;">​</a></h3><p>Several fields must be completed in order to add the new property. Some field options (such as <em><strong>range/type: Text</strong></em>) allow further customization of the property.</p><h3 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Only editable at the time of property creation.</p></div><p>Custom properties in CaSS are stored as namespaced linked JSON-LD records. Because of this, all new properties must have a context. By default, all custom properties have the <strong>CaSS v4.0</strong> <a href="https://schema.cassproject.org/0.4/" target="_blank" rel="noreferrer">[schema]</a> context. However, it is also possible to modify this field to the following values:</p><ul><li><strong>CTDL-ASN</strong> - <a href="https://purl.org/ctdlasn/terms/" target="_blank" rel="noreferrer">https://purl.org/ctdlasn/terms/</a></li><li><strong>RDF Semantic Web Standards 1999</strong> - <a href="http://www.w3.org/1999/02/22-rdf-syntax-ns#" target="_blank" rel="noreferrer">http://www.w3.org/1999/02/22-rdf-syntax-ns#</a></li><li><strong>RDF Semantic Web Standards 2000</strong> - <a href="http://www.w3.org/2000/01/rdf-schema#" target="_blank" rel="noreferrer">http://www.w3.org/2000/01/rdf-schema#</a></li><li><strong>Key Based Authorization and Control</strong> - <a href="https://schema.cassproject.org/kbac/0.4/" target="_blank" rel="noreferrer">https://schema.cassproject.org/kbac/0.4/</a></li><li><strong>Eduworks v3.0</strong> - <a href="http://schema.eduworks.com/general/0.3/" target="_blank" rel="noreferrer">http://schema.eduworks.com/general/0.3/</a></li><li><strong>Schema.org</strong> - <a href="http://schema.org/" target="_blank" rel="noreferrer">http://schema.org/</a></li><li><strong>Achievements Standard Network</strong> - <a href="http://purl.org/ASN/schema/core/" target="_blank" rel="noreferrer">http://purl.org/ASN/schema/core/</a></li><li><strong>DCMI Elements v1.1</strong> - <a href="http://purl.org/dc/elements/1.1/" target="_blank" rel="noreferrer">http://purl.org/dc/elements/1.1/</a></li><li><strong>DCMI Terms</strong> - <a href="http://purl.org/dc/terms/" target="_blank" rel="noreferrer">http://purl.org/dc/terms/</a></li><li><strong>Gem v2.0</strong> - <a href="http://purl.org/gem/qualifiers/" target="_blank" rel="noreferrer">http://purl.org/gem/qualifiers/</a></li><li><strong>Relators Scheme</strong> - <a href="http://www.loc.gov/loc.terms/relators/" target="_blank" rel="noreferrer">http://www.loc.gov/loc.terms/relators/</a></li><li><strong>Simple Knowledge Organization System</strong> - <a href="http://www.w3.org/2004/02/skos/core#" target="_blank" rel="noreferrer">http://www.w3.org/2004/02/skos/core#</a></li></ul><p>It is highly recommended to accept the default for this field unless there is an actionable reason for not doing so.</p><h3 id="range-type" tabindex="-1">Range/Type <a class="header-anchor" href="#range-type" aria-label="Permalink to &quot;Range/Type&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only editable at the time of property creation.</p></div><p>The <em><strong>range/type</strong></em> field defines the property type. Certain <em>range/types</em> allow for further customization of the property. The following values are available for this field:</p><ul><li><strong>Lang-String</strong> - An RDF schema lang string as defined by <a href="http://www.w3.org/2000/01/rdf-schema#langString" target="_blank" rel="noreferrer">http://www.w3.org/2000/01/rdf-schema#langString</a>. <ul><li>Selecting this value opens the <em>One Entry Per Language</em> property field</li></ul></li><li><strong>URL</strong> - A schema.org URL as defined by <a href="http://schema.org/URL" target="_blank" rel="noreferrer">http://schema.org/URL</a></li><li><strong>Text</strong> - A schema.org Text (plain string) value as defined by <a href="http://schema.org/Text" target="_blank" rel="noreferrer">http://schema.org/Text</a><ul><li>Selecting this value opens the <em>Limit Values</em> property field</li></ul></li><li><strong>Date-Time</strong> - A w3.org dateTime value as defined by <a href="http://www.w3.org/2001/XMLSchema#dateTime" target="_blank" rel="noreferrer">http://www.w3.org/2001/XMLSchema#dateTime</a></li><li><strong>Date</strong> - A dublin core date value as defined by <a href="http://purl.org/dc/terms/date" target="_blank" rel="noreferrer">http://purl.org/dc/terms/date</a></li><li><strong>SKOS Concept</strong> - A CaSS concept value as defined by <a href="https://schema.cassproject.org/0.4/skos/Concept" target="_blank" rel="noreferrer">https://schema.cassproject.org/0.4/skos/Concept</a></li><li><strong>Competency</strong> - A CaSS competency ID</li></ul><h3 id="display-priority" tabindex="-1">Display Priority <a class="header-anchor" href="#display-priority" aria-label="Permalink to &quot;Display Priority&quot;">​</a></h3><p>The priority in which the property is displayed in form inputs (<em>primary, secondary, or tertiary</em>).</p><h3 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;Required&quot;">​</a></h3><p>The property is required toggle.</p><h3 id="unique-property-identifier" tabindex="-1">Unique Property Identifier <a class="header-anchor" href="#unique-property-identifier" aria-label="Permalink to &quot;Unique Property Identifier&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only editable at the time of property creation.</p></div><p>The alphanumeric name of the property in the data record.</p><h3 id="display-label" tabindex="-1">Display Label <a class="header-anchor" href="#display-label" aria-label="Permalink to &quot;Display Label&quot;">​</a></h3><p>The label to be displayed in form inputs for the property.</p><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>The description of the property.</p><h3 id="display-category" tabindex="-1">Display Category <a class="header-anchor" href="#display-category" aria-label="Permalink to &quot;Display Category&quot;">​</a></h3><p>The category (if any) under which the property is displayed in form inputs.</p><h3 id="one-entry-per-language" tabindex="-1">One Entry Per Language <a class="header-anchor" href="#one-entry-per-language" aria-label="Permalink to &quot;One Entry Per Language&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only available for <em><strong>range/type=Lang-String</strong></em></p></div><p><img src="'+r+'" alt="One Entry Per Language"></p><p>By toggling this field on, custom properties of the <em><strong>range/type Lang-String</strong></em> can be limited so that only a single entry can be made per language chosen.</p><h3 id="limit-values" tabindex="-1">Limit Values <a class="header-anchor" href="#limit-values" aria-label="Permalink to &quot;Limit Values&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only available for <em><strong>range/type=Text</strong></em></p></div><p>When creating a custom property of <em><strong>range/type Text</strong></em>, you can limit the values allowed to the property. To do this, toggle the <em><strong>Limit Values</strong></em> field on and click the <em><strong>add</strong></em> button to begin managing the list of allowable values.</p><p><img src="'+c+'" alt="Limit Values"></p><p>For each entry in the limit values table, a <em><strong>display label</strong></em> and <em><strong>field value</strong></em> must be entered.</p><ul><li><em><strong>display label</strong></em> - the label displayed to the user when selecting the value</li><li><em><strong>field value</strong></em> - the recorded value when the value is selected by the user <ul><li>Only alphanumerics are allowed for field values</li></ul></li></ul><p><img src="'+m+'" alt="Limit Values Enabled"></p><h3 id="limit-concepts" tabindex="-1">Limit Concepts <a class="header-anchor" href="#limit-concepts" aria-label="Permalink to &quot;Limit Concepts&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only available for <em><strong>range/type=SKOS Concept</strong></em></p></div><p>When creating a custom property of <em><strong>range/type SKOS Concept</strong></em>, you can limit the concepts to apply to the property. To do this, toggle the <em><strong>Limit Concepts</strong></em> field on and begin typing in the search box. A dropdown list will contain existing Concept Schemes or Taxonomies that match your search. Select one or more of the Concept Schemes or Taxonomies. Each selected item will appear above the search box and can be removed again if desired.</p><p><img src="'+d+'" alt="Limit Concepts"></p><p>When searching for a value to apply to a property of type SKOS Concept with limited concepts, only concepts defined within the Limit Concepts configuration will be available to select from.</p><h3 id="limit-types" tabindex="-1">Limit Types <a class="header-anchor" href="#limit-types" aria-label="Permalink to &quot;Limit Types&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only available for <em><strong>range/type=Competency</strong></em></p></div><p>When creating a custom property of <em><strong>range/type Competency</strong></em>, you can limit the available competencies to apply to the property. To do this, you must first have Competency Types defined in the configuration. [To add Competency Types, please refer to Restrict Competency Types (#restrict-competency-types). Toggle the <em><strong>Limit By Type</strong></em> field on and begin typing in the search box. A dropdown list will contain existing Competency Types that match your search. Select one or more of the Competency Types. Each selected Competency Type will appear above the search box and can be removed again if desired.</p><p><img src="'+h+'" alt="Limit By Type"></p><p>When searching for a value to apply to a property of type Competency, only values with the Competency Type defined in the Limit By Type configuration will be available in the search.</p><p>In the example below, &quot;Critical Skill&quot; is a property of type Competency. In the configuration, it is limited by type &quot;Major&quot;. The two competencies listed in the search below, &quot;Emergency Response Preparedness&quot; and &quot;Threat Awareness&quot;, both have the Competency Type of &quot;Major&quot; applied to them and therefore show up as options to apply to &quot;Critical Skill&quot;. The value of the &quot;Critical Skill&quot; property will be set to the id of the competency selected from the search.</p><p><img src="'+g+'" alt="Competency Limited By Type"></p><h2 id="applying-the-custom-competency-property" tabindex="-1">Applying the Custom Competency Property <a class="header-anchor" href="#applying-the-custom-competency-property" aria-label="Permalink to &quot;Applying the Custom Competency Property&quot;">​</a></h2><p>Once complete, the new property can be applied to the framework by clicking the <em><strong>apply new property</strong></em> in the lower right corner of the dialogue window.</p><h2 id="editing-deleting-custom-competency-properties" tabindex="-1">Editing/Deleting Custom Competency Properties <a class="header-anchor" href="#editing-deleting-custom-competency-properties" aria-label="Permalink to &quot;Editing/Deleting Custom Competency Properties&quot;">​</a></h2><p>Custom properties can be edited and deleted by selecting the appropriate action buttons to the right of the corresponding property entry in the <em><strong>Competency Properties</strong></em> list.</p><p><img src="'+y+'" alt="Delete Custom Properties"></p><h2 id="restrict-competency-types" tabindex="-1">Restrict Competency Types <a class="header-anchor" href="#restrict-competency-types" aria-label="Permalink to &quot;Restrict Competency Types&quot;">​</a></h2><p>By default, values for the competency <em><strong>type</strong></em> property are not limited. By toggling this setting, competency types can be restricted to a list of predetermined values.</p><p><img src="'+u+'" alt="Restrict Competency Types"></p><p>For each entry in the permitted values table, a <em><strong>display label</strong></em> and <em><strong>field value</strong></em> must be entered.</p><ul><li><em><strong>display label</strong></em> - the label displayed to the user when selecting the type value</li><li><em><strong>field value</strong></em> - the recorded value when the type is selected by the user <ul><li>Only alphanumerics are allowed for field values</li></ul></li></ul><p><img src="'+f+'" alt="Permitted Values Table"></p><h2 id="competency-levels" tabindex="-1">Competency Levels <a class="header-anchor" href="#competency-levels" aria-label="Permalink to &quot;Competency Levels&quot;">​</a></h2><p>By default, the level property is enabled for competency objects created in the CaSS Authoring Tool. Levels can be disabled by toggling the <em><strong>allow levels</strong></em> switch.</p><p><img src="'+b+'" alt="Allow Levels"></p><h2 id="level-property-fields" tabindex="-1">Level Property Fields <a class="header-anchor" href="#level-property-fields" aria-label="Permalink to &quot;Level Property Fields&quot;">​</a></h2><p>Level property fields can be modified from the <em><strong>allow levels</strong></em> section of the competency configuration settings:</p><ul><li><em><strong>display label</strong></em> - label to be displayed in form inputs for levels</li><li><em><strong>description</strong></em> - description of the levels property</li><li><em><strong>display category</strong></em> - category (if any) under which levels are displayed in form inputs</li><li><em><strong>level display priority</strong></em> - priority in which levels are displayed in form inputs (primary, secondary, or tertiary)</li></ul><h2 id="restrict-competency-levels" tabindex="-1">Restrict Competency Levels <a class="header-anchor" href="#restrict-competency-levels" aria-label="Permalink to &quot;Restrict Competency Levels&quot;">​</a></h2><p>By default, levels in CaSS can be created during framework/competency editing. To restrict competencies that allow levels to a limited selection, toggle the <em><strong>restrict level values</strong></em> switch and click the <em><strong>manage levels</strong></em> button.</p><p><img src="'+v+'" alt="Restrict Competency Levels"></p><h3 id="manage-competency-levels" tabindex="-1">Manage Competency Levels <a class="header-anchor" href="#manage-competency-levels" aria-label="Permalink to &quot;Manage Competency Levels&quot;">​</a></h3><p>Clicking the <em><strong>manage levels</strong></em> button displays the <em><strong>select enforced levels</strong></em> dialogue screen. From here, you can select from all existing levels in CaSS or create more appropriate levels. Any previously selected levels will already be checked and can be removed from the enforced levels list by unchecking the appropriate item.</p><p><img src="'+w+'" alt="Enforced Levels"></p><h3 id="add-competency-levels" tabindex="-1">Add Competency Levels <a class="header-anchor" href="#add-competency-levels" aria-label="Permalink to &quot;Add Competency Levels&quot;">​</a></h3><p>To add a new level to the available level list, click on the <em><strong>add level</strong></em> button in the <em><strong>select enforced levels</strong></em> dialogue window.</p><p><img src="'+C+'" alt="Add Levels"></p><p>Once clicked, the <em><strong>add new level</strong></em> dialogue is open. Enter the new level&#39;s <em><strong>name</strong></em> (and optionally the new level&#39;s <em><strong>description</strong></em> ). Clicking the <em><strong>save new level</strong></em> button on the bottom right corner of the dialogue will create this level in CaSS and return you to the <em><strong>select enforced levels</strong></em> dialogue.</p><p><img src="'+k+'" alt="Add New Level Modal"></p><h3 id="apply-selected-competency-levels" tabindex="-1">Apply Selected Competency Levels <a class="header-anchor" href="#apply-selected-competency-levels" aria-label="Permalink to &quot;Apply Selected Competency Levels&quot;">​</a></h3><p>Upon selecting the desired enforced levels, click the <em><strong>apply selected</strong></em> button at the bottom right of the <em><strong>select enforced levels</strong></em> dialog window to apply the enforced levels to competencies.</p><p><img src="'+q+'" alt="Select Enforced Levels"></p><h2 id="competency-relationships-configuration" tabindex="-1">Competency Relationships Configuration <a class="header-anchor" href="#competency-relationships-configuration" aria-label="Permalink to &quot;Competency Relationships Configuration&quot;">​</a></h2><p>Relationships can be added as properties on competencies to define how competencies within a framework relate to each other. Enabled relationships will be available in the property drop down when editing competencies in the framework editor.</p><p><img src="'+T+'" alt="Competnecy Relationship Configuration"></p><h3 id="relationship-display-options" tabindex="-1">Relationship Display Options <a class="header-anchor" href="#relationship-display-options" aria-label="Permalink to &quot;Relationship Display Options&quot;">​</a></h3><p>General relationship display options can be configured from the <em><strong>display options section</strong></em>. These include:</p><ul><li><em><strong>display category</strong></em> - category (if any) under which relationships are displayed in form inputs</li><li><em><strong>relationships display priority</strong></em> - priority in which relationships are displayed in form inputs (<em>primary, secondary, or tertiary</em>)</li></ul><p><img src="'+_+'" alt="Relationship Display Options"></p><h3 id="relationship-type-management" tabindex="-1">Relationship Type Management <a class="header-anchor" href="#relationship-type-management" aria-label="Permalink to &quot;Relationship Type Management&quot;">​</a></h3><p>The types of relationships available to competencies using the configuration can be managed under the <em><strong>relationship types</strong></em> section. Relationship types can be <em>enabled, disabled,</em> and <em>relabeled</em>.</p><p>By default, the following relationship types are enabled:</p><ul><li><em><strong>isEnabledBy</strong></em></li><li><em><strong>requires</strong></em></li><li><em><strong>desires</strong></em></li><li><em><strong>narrows</strong></em></li><li><em><strong>isRelatedTo</strong></em></li><li><em><strong>isEquivalentTo</strong></em></li></ul><p><img src="'+t+'" alt="Relationship Types Management"></p><p>To reduce screen clutter, the <em><strong>relationship types</strong></em> section only displays <em>enabled</em> relationship types. Currently, enabled relationships can be disabled using the corresponding <em><strong>enabled</strong></em> switch to the right of the relationship entry.</p><p><img src="'+S+'" alt="Relationship Types Enabled Toggle"></p><p>To add other relationship types to a configuration, click on the <em><strong>manage relationships</strong></em> button on the upper right of the <em><strong>relationship types</strong></em> section.</p><p><img src="'+P+'" alt="Manage Relationships"></p><p>Once clicked, the <em><strong>manage relationship types</strong></em> dialogue window is open. From this screen, all relationships type currently available in CaSS are categorized and displayed.</p><p><img src="'+t+'" alt="Manage Relationship Types"></p><p>The available relationship types are as follows:</p><ul><li><strong>CaSS Default Relationships</strong><ul><li>isEnabledBy</li><li>requires</li><li>desires</li><li>narrows</li><li>isRelatedTo</li><li>isEquivalentTo</li><li>broadens</li><li>enables</li></ul></li><li><strong>Achievement Standards Network Relationships</strong><ul><li>majorRelated</li><li>minorRelated</li></ul></li><li><strong>GEMQ</strong><ul><li>hasChild</li><li>isChildOf</li></ul></li><li><strong>Other</strong><ul><li>isSimilarTo</li><li>isPartiallySameAs</li></ul></li></ul><p>To enable or disable a relationship type for the configuration, toggle the <em><strong>enabled</strong></em> switch to the right of the corresponding type and click the <em><strong>ok</strong></em> button.</p><h2 id="resource-alignment-configuration" tabindex="-1">Resource Alignment Configuration <a class="header-anchor" href="#resource-alignment-configuration" aria-label="Permalink to &quot;Resource Alignment Configuration&quot;">​</a></h2><p>Resource alignment terms are used to map resources such as learning material, courses, and other content to competencies in CAT. If enabled, the alignment type property will show up in the framework editor when aligning competencies to resources.</p><p><img src="'+x+'" alt="Resource Alignemnt Configuration"></p><p>Currently, the CaSS Authoring Tool supports four types of resource alignments:</p><ul><li><strong>teaches</strong> - The item being described is intended to help a person learn the competency or learning outcome defined by the referenced term</li><li><strong>assesses</strong> - The learning resource being described may be used to assess the competency being referenced</li><li><strong>requires</strong> - The competency being referenced is required in order for effective outcome of the learning resource being described</li><li><strong>desires</strong> - Knowledge of the learning resource being described is desired by the competency being referenced</li></ul><p>Each alignment type can be enabled and disabled by toggling the <em><strong>enabled</strong></em> switch to the right of each corresponding item.</p>',118)])])}const W=o(L,[["render",R]]);export{M as __pageData,W as default};
